-- Piw schema v1.
--
-- Conventions
-- * Ids are UUIDv7 strings generated by the app (time-ordered, stable across exports).
-- * Timestamps are UTC ISO-8601 with milliseconds ("2026-11-06T12:00:00.000Z"), so text order
--   is chronological. Due dates are calendar dates ("YYYY-MM-DD"), deliberately without time.
-- * `rev` increments on every *text* edit and guards autosave against concurrent edits from
--   other windows (optimistic concurrency). Metadata changes do not bump it.
-- * Soft delete: `deleted_at` (Trash) and `archived_at` (notes only). Nothing is purged without
--   an explicit user action.

CREATE TABLE spaces (
    id          TEXT PRIMARY KEY NOT NULL,
    name        TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 80),
    color       TEXT CHECK (color IN ('yellow', 'peach', 'rose', 'mint', 'sky', 'lavender')),
    sort_order  INTEGER NOT NULL,
    is_default  INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
CREATE UNIQUE INDEX spaces_name_unique ON spaces (name COLLATE NOCASE);
-- At most one default space; the service guarantees there is always exactly one.
CREATE UNIQUE INDEX spaces_single_default ON spaces (is_default) WHERE is_default = 1;

-- Quick notes and documents share one table: a document is a note with tabs.
CREATE TABLE notes (
    id             TEXT PRIMARY KEY NOT NULL,
    space_id       TEXT NOT NULL REFERENCES spaces (id) ON DELETE RESTRICT,
    kind           TEXT NOT NULL CHECK (kind IN ('quick_note', 'document')),
    title          TEXT NOT NULL DEFAULT '' CHECK (length(title) <= 300),
    -- Markdown-friendly plain text for quick notes; NULL for documents (content lives in tabs).
    body           TEXT,
    -- A quick note grouped under a document (documents are never nested).
    document_id    TEXT REFERENCES notes (id) ON DELETE SET NULL,
    -- Position in the sidebar "Documents" section; NULL = not a favourite.
    sidebar_order  INTEGER,
    rev            INTEGER NOT NULL DEFAULT 1,
    triaged_at     TEXT,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    archived_at    TEXT,
    deleted_at     TEXT,
    CHECK (kind = 'quick_note' OR body IS NULL),
    CHECK (kind = 'quick_note' OR document_id IS NULL),
    CHECK (kind = 'document' OR sidebar_order IS NULL),
    CHECK (document_id IS NULL OR document_id <> id)
);
CREATE INDEX notes_space ON notes (space_id);
CREATE INDEX notes_document ON notes (document_id) WHERE document_id IS NOT NULL;
CREATE INDEX notes_live_updated ON notes (updated_at DESC) WHERE deleted_at IS NULL;

CREATE TRIGGER notes_document_must_be_document
BEFORE INSERT ON notes
WHEN NEW.document_id IS NOT NULL
 AND (SELECT kind FROM notes WHERE id = NEW.document_id) IS NOT 'document'
BEGIN
    SELECT RAISE(ABORT, 'document_id must reference a document');
END;

CREATE TRIGGER notes_document_must_be_document_update
BEFORE UPDATE OF document_id ON notes
WHEN NEW.document_id IS NOT NULL
 AND (SELECT kind FROM notes WHERE id = NEW.document_id) IS NOT 'document'
BEGIN
    SELECT RAISE(ABORT, 'document_id must reference a document');
END;

CREATE TABLE document_tabs (
    id            TEXT PRIMARY KEY NOT NULL,
    document_id   TEXT NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    title         TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 80),
    kind          TEXT NOT NULL CHECK (kind IN ('content', 'tasks')),
    sort_order    INTEGER NOT NULL,
    -- Canonical ProseMirror JSON (content tabs only); see docs/architecture.md#documents-and-the-editor.
    content_json  TEXT,
    -- Plain text derived from content_json, kept for full-text search.
    plain_text    TEXT NOT NULL DEFAULT '',
    -- JSON settings for tasks tabs: {"show": "open"|"all"|"completed", "sort": "manual"|"due_date"}.
    settings      TEXT,
    rev           INTEGER NOT NULL DEFAULT 1,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    deleted_at    TEXT,
    CHECK (kind = 'content' OR content_json IS NULL),
    CHECK (content_json IS NULL OR json_valid(content_json)),
    CHECK (settings IS NULL OR json_valid(settings))
);
CREATE INDEX document_tabs_document ON document_tabs (document_id, sort_order);

CREATE TRIGGER document_tabs_parent_must_be_document
BEFORE INSERT ON document_tabs
WHEN (SELECT kind FROM notes WHERE id = NEW.document_id) IS NOT 'document'
BEGIN
    SELECT RAISE(ABORT, 'tabs belong to documents');
END;

CREATE TABLE tasks (
    id              TEXT PRIMARY KEY NOT NULL,
    space_id        TEXT NOT NULL REFERENCES spaces (id) ON DELETE RESTRICT,
    document_id     TEXT REFERENCES notes (id) ON DELETE SET NULL,
    parent_task_id  TEXT REFERENCES tasks (id) ON DELETE CASCADE,
    title           TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 500),
    description     TEXT NOT NULL DEFAULT '',
    status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'completed')),
    due_date        TEXT CHECK (due_date IS NULL OR date(due_date) = due_date),
    completed_at    TEXT,
    sort_order      INTEGER NOT NULL,
    rev             INTEGER NOT NULL DEFAULT 1,
    triaged_at      TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    deleted_at      TEXT,
    CHECK ((status = 'completed') = (completed_at IS NOT NULL)),
    CHECK (parent_task_id IS NULL OR parent_task_id <> id)
);
CREATE INDEX tasks_space ON tasks (space_id);
CREATE INDEX tasks_document ON tasks (document_id) WHERE document_id IS NOT NULL;
CREATE INDEX tasks_parent ON tasks (parent_task_id) WHERE parent_task_id IS NOT NULL;
CREATE INDEX tasks_open_due ON tasks (due_date, sort_order)
    WHERE deleted_at IS NULL AND status = 'open' AND parent_task_id IS NULL;

-- Subtasks are one level deep: a subtask's parent must itself be a top-level task.
CREATE TRIGGER tasks_single_level_subtasks
BEFORE INSERT ON tasks
WHEN NEW.parent_task_id IS NOT NULL
 AND (SELECT parent_task_id FROM tasks WHERE id = NEW.parent_task_id) IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'subtasks cannot have subtasks');
END;

CREATE TRIGGER tasks_document_must_be_document
BEFORE INSERT ON tasks
WHEN NEW.document_id IS NOT NULL
 AND (SELECT kind FROM notes WHERE id = NEW.document_id) IS NOT 'document'
BEGIN
    SELECT RAISE(ABORT, 'document_id must reference a document');
END;

CREATE TRIGGER tasks_document_must_be_document_update
BEFORE UPDATE OF document_id ON tasks
WHEN NEW.document_id IS NOT NULL
 AND (SELECT kind FROM notes WHERE id = NEW.document_id) IS NOT 'document'
BEGIN
    SELECT RAISE(ABORT, 'document_id must reference a document');
END;

CREATE TABLE tags (
    id          TEXT PRIMARY KEY NOT NULL,
    name        TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 40),
    created_at  TEXT NOT NULL
);
CREATE UNIQUE INDEX tags_name_unique ON tags (name COLLATE NOCASE);

-- Separate join tables keep real foreign keys (no polymorphic references).
CREATE TABLE note_tags (
    note_id  TEXT NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    tag_id   TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    PRIMARY KEY (note_id, tag_id)
) WITHOUT ROWID;
CREATE INDEX note_tags_tag ON note_tags (tag_id);

CREATE TABLE task_tags (
    task_id  TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    tag_id   TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    PRIMARY KEY (task_id, tag_id)
) WITHOUT ROWID;
CREATE INDEX task_tags_tag ON task_tags (tag_id);

-- One row per pinned item: the row's existence means "pinned to desktop" (shown in Pinned);
-- `is_open` says whether its window is currently on screen.
CREATE TABLE sticky_windows (
    target_kind    TEXT NOT NULL CHECK (target_kind IN ('note', 'task', 'tasks_tab')),
    target_id      TEXT NOT NULL,
    x              INTEGER,
    y              INTEGER,
    width          REAL NOT NULL CHECK (width > 0),
    height         REAL NOT NULL CHECK (height > 0),
    always_on_top  INTEGER NOT NULL DEFAULT 0 CHECK (always_on_top IN (0, 1)),
    color          TEXT CHECK (color IN ('yellow', 'peach', 'rose', 'mint', 'sky', 'lavender')),
    is_open        INTEGER NOT NULL DEFAULT 1 CHECK (is_open IN (0, 1)),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    PRIMARY KEY (target_kind, target_id)
) WITHOUT ROWID;

-- Polymorphic target: clean up when the item is permanently deleted.
CREATE TRIGGER sticky_cleanup_note AFTER DELETE ON notes BEGIN
    DELETE FROM sticky_windows WHERE target_kind = 'note' AND target_id = OLD.id;
END;
CREATE TRIGGER sticky_cleanup_task AFTER DELETE ON tasks BEGIN
    DELETE FROM sticky_windows WHERE target_kind = 'task' AND target_id = OLD.id;
END;
CREATE TRIGGER sticky_cleanup_tab AFTER DELETE ON document_tabs BEGIN
    DELETE FROM sticky_windows WHERE target_kind = 'tasks_tab' AND target_id = OLD.id;
END;

CREATE TABLE settings (
    key         TEXT PRIMARY KEY NOT NULL,
    value       TEXT NOT NULL CHECK (json_valid(value)),
    updated_at  TEXT NOT NULL
) WITHOUT ROWID;

-- Unsaved Quick Capture text, so an accidental close never loses it.
CREATE TABLE capture_drafts (
    id          TEXT PRIMARY KEY NOT NULL,
    content     TEXT NOT NULL CHECK (json_valid(content)),
    updated_at  TEXT NOT NULL
) WITHOUT ROWID;

-- Full-text search over titles and text. Kept in sync by triggers so it can never drift.
-- `entity_kind`: note | document | task | tab. Tabs point at their document via `document_id`.
CREATE VIRTUAL TABLE search_index USING fts5 (
    entity_kind UNINDEXED,
    entity_id UNINDEXED,
    document_id UNINDEXED,
    title,
    body,
    tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER search_notes_insert AFTER INSERT ON notes BEGIN
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES (CASE NEW.kind WHEN 'document' THEN 'document' ELSE 'note' END,
            NEW.id, NULL, NEW.title, coalesce(NEW.body, ''));
END;
CREATE TRIGGER search_notes_update AFTER UPDATE OF title, body, kind ON notes BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind IN ('note', 'document');
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES (CASE NEW.kind WHEN 'document' THEN 'document' ELSE 'note' END,
            NEW.id, NULL, NEW.title, coalesce(NEW.body, ''));
END;
CREATE TRIGGER search_notes_delete AFTER DELETE ON notes BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind IN ('note', 'document');
END;

CREATE TRIGGER search_tasks_insert AFTER INSERT ON tasks BEGIN
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES ('task', NEW.id, NULL, NEW.title, NEW.description);
END;
CREATE TRIGGER search_tasks_update AFTER UPDATE OF title, description ON tasks BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind = 'task';
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES ('task', NEW.id, NULL, NEW.title, NEW.description);
END;
CREATE TRIGGER search_tasks_delete AFTER DELETE ON tasks BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind = 'task';
END;

CREATE TRIGGER search_tabs_insert AFTER INSERT ON document_tabs BEGIN
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES ('tab', NEW.id, NEW.document_id, NEW.title, NEW.plain_text);
END;
CREATE TRIGGER search_tabs_update AFTER UPDATE OF title, plain_text ON document_tabs BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind = 'tab';
    INSERT INTO search_index (entity_kind, entity_id, document_id, title, body)
    VALUES ('tab', NEW.id, NEW.document_id, NEW.title, NEW.plain_text);
END;
CREATE TRIGGER search_tabs_delete AFTER DELETE ON document_tabs BEGIN
    DELETE FROM search_index WHERE entity_id = OLD.id AND entity_kind = 'tab';
END;
